17-tempo-e-sistema.codigo:
// Exercicio 161 — Executando processos
// Enunciado: rode comandos externos e trate a saida.

adopt Arcane.Process as Proc
adopt Arcane.OS as OS

// ── O comando externo e onde o programa deixa de ser portatil ──
//
// 'echo' existe no Linux e no macOS como programa; no Windows ele e
// embutido do interpretador de comandos, e nao ha arquivo para rodar.
// 'cat' se chama 'more', e 'sleep' se chama 'timeout'.
//
// Por isso o primeiro passo de um programa que chama o sistema e
// decidir COM QUEM esta falando. O resto do exercicio e igual nos dois.

steady WINDOWS := OS.is_windows()
steady NL := char(10)

steady ECO := "cmd /c echo" given WINDOWS otherwise "echo"

// Comando que demora, para a demonstracao de tempo limite. O 'timeout'
// do Windows recusa entrada redirecionada e sai na hora; o 'ping' para
// o proprio computador espera de verdade nos dois sistemas.
steady DEMORA := "ping -n 6 127.0.0.1" given WINDOWS otherwise "sleep 5"

// run devolve stdout, stderr e o codigo de saida
r := Proc.run($"{ECO} ola do processo")
out $"saida:  {r.stdout.trim()}"
out $"codigo: {r.exit_code}"
out $"ok:     {r.ok}"

assert r.ok is yes, "o eco funciona"
assert r.exit_code is 0, "codigo zero"
assert r.stdout.trim() is "ola do processo", "a saida"

// capture pega so o stdout, ja limpo
out ""
out $"capture: '{Proc.capture($"{ECO} direto")}'"
assert Proc.capture($"{ECO} direto") is "direto", "capture"

// Comando inexistente nao derruba o programa
falhou := Proc.run("comando_que_nao_existe_xyz")
out ""
out $"inexistente -> codigo {falhou.exit_code}, ok={falhou.ok}"
assert falhou.ok is no, "falhou"
// 127 nos DOIS: a linguagem normaliza. O Windows levanta um erro do
// sistema em vez de devolver codigo, e 'Arcane.Process' traduz — quem
// escreve nao precisa saber de qual lado esta.
assert falhou.exit_code is 127, "o codigo de comando nao encontrado"

// check devolve so yes/no
out ""
out $"xyz existe?  {Proc.exists("comando_inexistente_xyz")}"
assert Proc.exists("comando_inexistente_xyz") is no, "o que nao existe"

// Argumentos com espacos: passe como lista, sem shell
//
// Sem lista, o espaco separaria em dois argumentos — e com um nome de
// arquivo vindo de fora, um espaco a mais vira uma falha de seguranca.
r2 := Proc.run([...ECO.split(" "), "texto com espacos"])
out ""
out $"lista: {r2.stdout.trim()}"

// A comparacao e por CONTEM, e nao por igual, de proposito: o 'cmd' do
// Windows reprocessa a linha e devolve as aspas junto com o texto. Isso
// nao enfraquece o teste — enfraqueceria se o argumento tivesse sido
// PARTIDO, e e exatamente isso que se esta cobrando. E e a melhor
// ilustracao de por que se passa lista: mesmo com lista, o que ha do
// outro lado ainda pode reinterpretar.
assert "texto com espacos" in r2.stdout, "a lista preserva o argumento"

// Enviar entrada para o processo
//
// 'sort' e um dos poucos que existe com o mesmo nome nos dois sistemas,
// e le da entrada padrao quando nao recebe arquivo.
r3 := Proc.run("sort", input_text := $"c{NL}a{NL}b{NL}")
ordenado := r3.lines >> morph l: l.trim() >> sift l: l isnt ""
out $"stdin ordenado: {ordenado}"
assert ordenado is ["a", "b", "c"], "a entrada padrao chegou e voltou ordenada"

// Encadear comandos: a saida de um vira a entrada do proximo
resultado := Proc.pipeline([$"{ECO} zebra", "sort"])
out ""
out $"pipeline: {resultado.stdout.trim()}"
assert resultado.stdout.trim() is "zebra", "a saida de um virou a entrada do outro"

// Tempo limite
lento := Proc.run(DEMORA, timeout := 1)
out ""
out $"com timeout: ok={lento.ok}"
assert lento.ok is no, "o comando estourou o tempo"

22-web-kiln.codigo:
// Exercicio 191 — O primeiro servidor
// Enunciado: declare um servidor com duas rotas e responda texto e HTML.

// 'server' declara a aplicacao; 'route' declara uma rota; 'respond'
// envia a resposta e encerra a rota, como 'yield' encerra uma acao.
// Nada sobe ainda: quem acende o forno e 'ignite'. Essa separacao e o
// que permite testar uma rota sem abrir socket nenhum.

adopt Kiln

server ola on 8080:
    route GET "/":
        respond html "<h1>Ola do Kiln</h1>"

    route GET "/ping":
        respond text "pong"

// Kiln.test executa o pedido direto na aplicacao, sem rede.
inicio := Kiln.test(ola, "GET", "/")
out "GET / ->", inicio["status"]
out inicio["body"]

pong := Kiln.test(ola, "GET", "/ping")
out "GET /ping ->", pong["body"]

assert inicio["status"] is 200, "a raiz responde 200"
assert pong["body"] is "pong", "o texto chega inteiro"
assert len(Kiln.routes(ola)) is 2, "duas rotas registradas"

// Um caminho que nao existe da 404 — sem precisar escrever isso.
assert Kiln.test(ola, "GET", "/nada")["status"] is 404, "404 automatico"

// Exercicio 192 — Parametros de caminho e query string
// Enunciado: leia :id do caminho e ?campo= da query.

// Dentro de uma rota voce ja tem seis nomes prontos: 'req', 'params',
// 'query', 'body', 'headers' e 'session'. Escrever
// req["params"]["id"] toda vez cansa; os atalhos existem por isso.

adopt Kiln

server api on 0:
    // ':id' casa um trecho; '*resto' casa o que sobrar, barras inclusive
    route GET "/usuarios/:id":
        respond json {"id": params["id"], "formato": query["f"] ?? "curto"}

    route GET "/arquivos/*caminho":
        respond json {"caminho": params["caminho"]}

curto := Kiln.test(api, "GET", "/usuarios/42")
out "sem query:", curto["body"]
assert curto["body"]["id"] is "42", "o parametro chega como texto"
assert curto["body"]["formato"] is "curto", "?? cobre a query ausente"

longo := Kiln.test(api, "GET", "/usuarios/42?f=longo")
out "com query:", longo["body"]["formato"]
assert longo["body"]["formato"] is "longo", "a query e lida"

fundo := Kiln.test(api, "GET", "/arquivos/notas/2026/marco.txt")
out "curinga:", fundo["body"]["caminho"]
assert fundo["body"]["caminho"] is "notas/2026/marco.txt", "'*' pega tudo"

// Exercicio 194 — Paginas HTML com template
// Enunciado: renderize uma pagina a partir de um template com laco.

// 'render' le um arquivo da pasta declarada em 'views' e devolve HTML.
// A sintaxe do template e pequena de proposito: {{nome}} escreve,
// {{#lista}}…{{/lista}} repete, {{^lista}}…{{/lista}} cobre o vazio e
// {{&bruto}} nao escapa. Template que vira linguagem e codigo escondido
// onde ninguem procura.

adopt Kiln
adopt Arcane.IO as IO
adopt Arcane.OS as OS

// escreve o template no disco para o exercicio ser auto-contido
pasta := IO.join(OS.temp_dir(), "kilnviews")
IO.mkdir(pasta)  // sem isto, so roda se a pasta ja existir
IO.write_file(pasta + "/lista.html", """<!doctype html>
<title>{{titulo}}</title>
<h1>{{titulo}}</h1>
{{#produtos}}<article><h2>{{nome}}</h2><p>R$ {{preco}}</p></article>
{{/produtos}}
{{^produtos}}<p>Nada na forja.</p>{{/produtos}}""")

produtos := [
    {"nome": "Martelo", "preco": 89.9},
    {"nome": "Bigorna <de aco>", "preco": 450.0}
]

server site on 0:
    views pasta

    route GET "/":
        render "lista.html" with {"titulo": "Forja", "produtos": produtos}

    route GET "/vazio":
        render "lista.html" with {"titulo": "Vazio", "produtos":[]}

pagina := Kiln.test(site, "GET", "/")
out pagina["body"]

assert "Martelo" in pagina["body"], "o laco do template repetiu"
// O escape e automatico: '<de aco>' nao vira tag.
assert "&lt;de aco&gt;" in pagina["body"], "HTML e escapado por padrao"
assert "<article>" in pagina["body"], "as tags do template ficam"

vazio := Kiln.test(site, "GET", "/vazio")
assert "Nada na forja" in vazio["body"], "{{^}} cobre a lista vazia"
assert "article" not in vazio["body"], "sem itens, sem artigos"

// Exercicio 195 — Middleware, autenticacao e limite de taxa
// Enunciado: proteja rotas e limite pedidos por IP.

// Middleware roda antes de toda rota. Se ele devolve uma resposta, a
// cadeia para ali — e assim que autenticacao e limite de taxa cortam o
// pedido antes de ele custar qualquer coisa. Se devolve void, o pedido
// segue, e o que ele guardou em req["state"] chega na rota.

adopt Kiln

usuarios := {"tk-ana": "Ana", "tk-bia": "Bia"}

action conferir(token):
    yield usuarios[token] ?? void

// A ordem importa. O limite vem primeiro: um pedido barrado pelo 'auth'
// nunca chegaria a ser contado, e quem esta martelando a porta com
// credenciais invalidas e justamente quem voce quer limitar.
server privado on 0:
    middleware Kiln.rate_limit(3, 60)
    middleware Kiln.auth(conferir)

    route GET "/eu":
        respond json {"usuario": req["state"]["user"]}

sem_token := Kiln.test(privado, "GET", "/eu")
out "sem credencial:", sem_token["status"], sem_token["headers"]["WWW-Authenticate"]
assert sem_token["status"] is 401, "sem token, 401"

errado := Kiln.test(privado, "GET", "/eu", void, {"Authorization": "Bearer nao-existe"})
out "token invalido:", errado["status"]
assert errado["status"] is 401, "token desconhecido tambem e 401"

certo := Kiln.test(privado, "GET", "/eu", void, {"Authorization": "Bearer tk-ana"})
out "autenticado:", certo["body"]["usuario"]
assert certo["body"]["usuario"] is "Ana", "o middleware passou o usuario adiante"

// O limite ja contou tres pedidos deste IP — inclusive os dois que o
// 'auth' recusou. O quarto nao passa, mesmo com credencial boa.
excedido := Kiln.test(privado, "GET", "/eu", void, {"Authorization": "Bearer tk-bia"})
out "quarto pedido:", excedido["status"]
assert excedido["status"] is 429, "o quarto pedido no minuto e recusado"
assert "Retry-After" in excedido["headers"], "e o cliente sabe quando voltar"

// Exercicio 197 — Subir o servidor de verdade
// Enunciado: acenda o forno, faca um pedido pela rede e apague.

// Ate aqui usamos Kiln.test, que executa a rota sem abrir socket. Agora
// o servidor de verdade: 'Kiln.serve' sobe em segundo plano e devolve a
// porta na hora (porta 0 deixa o sistema escolher uma livre — util em
// teste, onde uma porta fixa daria conflito). Em producao voce usa
// 'ignite', que bloqueia ate o Ctrl-C.

adopt Kiln
adopt Arcane.Web as Web

visitas := 0

server contador on 0:
    route GET "/":
        respond html "<h1>Forja</h1>"

    route GET "/contar":
        visitas += 1
        respond json {"visitas": visitas}

porta := Kiln.serve(contador, 0)
out "no ar na porta", porta

pagina := Web.get($"http://127.0.0.1:{porta}/")
out "pela rede:", pagina["status"], pagina["body"]
assert pagina["status"] is 200, "o servidor respondeu de verdade"
assert "Forja" in pagina["body"], "o HTML chegou inteiro"

Web.get($"http://127.0.0.1:{porta}/contar")
Web.get($"http://127.0.0.1:{porta}/contar")
terceira := Web.get($"http://127.0.0.1:{porta}/contar")
out "tres pedidos:", terceira["body"]
assert visitas is 3, "o estado do programa sobrevive entre pedidos"

numeros := Kiln.stats(contador)
out "estatisticas:", numeros["pedidos"], "pedidos,", numeros["rotas"], "rotas"
assert numeros["pedidos"] is 4, "quatro pedidos contados"
assert numeros["erros"] is 0, "nenhum erro"

Kiln.stop(contador)
out "forno apagado"

// Em um programa de verdade, a ultima linha seria:
//     ignite contador on 8080
// que sobe e fica servindo ate voce apertar Ctrl-C.

23-dados-e-planilhas.codigo:
// Exercicio 198 — Gravar e ler uma planilha
// Enunciado: transforme uma lista de vaults num .xlsx e leia de volta.

// Um .xlsx e um ZIP de arquivos XML. O Arcane.Excel escreve e le esse
// formato sem nenhuma dependencia externa — o arquivo abre no Excel, no
// LibreOffice e no Google Sheets.

adopt Arcane.Excel as Xls
adopt Arcane.OS as OS
adopt Arcane.IO as IO

vendas := [
    {"produto": "Martelo", "qtd": 12, "preco": 89.9},
    {"produto": "Bigorna", "qtd": 3, "preco": 450.0},
    {"produto": "Tenaz", "qtd": 27, "preco": 65.5}
]

// Quando os dados sao vaults, o cabecalho sai das chaves — em negrito,
// com a primeira linha congelada e a largura ajustada ao conteudo.
Xls.quick(IO.join(OS.temp_dir(), "vendas.xlsx"), vendas, "Vendas")
out "planilha gravada"

livro := Xls.read(IO.join(OS.temp_dir(), "vendas.xlsx"))
out "abas:", Xls.sheets(livro)
out "tamanho:", Xls.dims(livro, "Vendas")

linhas := Xls.rows(livro, "Vendas")
out "cabecalho:", linhas[0]
out "primeira linha:", linhas[1]

assert linhas[0] is ["produto", "qtd", "preco"], "o cabecalho veio das chaves"
assert linhas[1][1] is 12, "o numero voltou numero, nao texto"

// 'records' devolve vaults de novo, usando a linha de cabecalho.
de_volta := Xls.records(livro, "Vendas")
assert len(de_volta) is 3, "tres registros"
assert de_volta[0]["produto"] is "Martelo", "ida e volta sem perda"

// Uma coluna inteira, pelo titulo.
assert Xls.column(livro, "Vendas", "qtd") is [12, 3, 27], "coluna pelo nome"

24-banco-de-dados.codigo:
// Exercicio 206 — Relacoes, e o problema do N+1
// Enunciado: carregue os pedidos de cem usuarios em duas consultas.

// Buscar cem usuarios e ler 'usuario.pedidos' de cada um faz cento e
// uma consultas. Isso nao aparece em desenvolvimento, com tres linhas
// na tabela, e derruba a producao com dez mil. E o bug de ORM mais
// comum que existe.

adopt Forge

db := Forge.conectar(":memory:")

Usuario := Forge.modelo("Usuario", {
        "id": {"tipo": "Serial"},
        "nome": {"tipo": "Texto", "obrigatorio": yes}
}, {"conexao": db})

Pedido := Forge.modelo("Pedido", {
        "id": {"tipo": "Serial"},
        "usuario_id": {"tipo": "Inteiro", "indice": yes},
        "total": {"tipo": "Real", "padrao": 0}
}, {"conexao": db})

Usuario.tem_muitos("pedidos", "Pedido")
Pedido.pertence_a("usuario", "Usuario")
Forge.migrar_tudo(db)

ana := Usuario.criar({"nome": "Ana"})
bia := Usuario.criar({"nome": "Bia"})
cid := Usuario.criar({"nome": "Cid"})

Pedido.criar({"usuario_id": ana["id"], "total": 100.0})
Pedido.criar({"usuario_id": ana["id"], "total": 50.0})
Pedido.criar({"usuario_id": bia["id"], "total": 20.0})

// A relacao NAO carrega sozinha ao ser lida — ou voce pede, ou ela
// nao vem. Ler uma relacao nao carregada devolveria void em vez de
// funcionar devagar.
com_pedidos := Usuario.com(Usuario.todos(), "pedidos")

cycle u in com_pedidos:
    out u["nome"], "tem", len(u["pedidos"]), "pedido(s)"

